const j = $input.first().json;
const m = j.metrics;
// Palette validated with dataviz six-checks (light surface): HOT/WARM/COLD
const BAND = { HOT: '#D64545', WARM: '#D98E21', COLD: '#3B6FD1' };
const BLUE = '#3B6FD1', INK = '#333333', MUTED = '#707070';
const qc = (cfg, w, h) => 'https://quickchart.io/chart?w=' + w + '&h=' + h + '&bkg=white&devicePixelRatio=2&c=' + encodeURIComponent(JSON.stringify(cfg));
const bands = ['HOT', 'WARM', 'COLD'].filter(b => (m.band_mix[b] || 0) > 0);
const donut = { type: 'doughnut',
  data: { labels: bands.map(b => b + ' (' + m.band_mix[b] + ')'), datasets: [{ data: bands.map(b => m.band_mix[b]), backgroundColor: bands.map(b => BAND[b]), borderColor: '#ffffff', borderWidth: 2 }] },
  options: { legend: { position: 'right', labels: { fontColor: INK, fontSize: 13 } }, plugins: { datalabels: { color: '#ffffff', font: { weight: 'bold', size: 14 } } } } };
const daily = { type: 'bar',
  data: { labels: (m.daily || []).map(d => d.day), datasets: [{ data: (m.daily || []).map(d => d.count), backgroundColor: BLUE }] },
  options: { legend: { display: false }, plugins: { datalabels: { anchor: 'end', align: 'top', color: MUTED, font: { size: 12 } } },
    scales: { yAxes: [{ ticks: { beginAtZero: true, stepSize: 1, fontColor: MUTED }, gridLines: { color: '#eeeeee' } }],
              xAxes: [{ ticks: { fontColor: MUTED }, gridLines: { display: false } }] } } };
const f = m.funnel;
const funnel = { type: 'horizontalBar',
  data: { labels: ['Received', 'Enquiries', 'Qualified', 'Recommended', 'Sent'],
    datasets: [{ data: [f.received, f.enquiries, f.qualified, f.recommended, f.sent], backgroundColor: BLUE }] },
  options: { legend: { display: false }, plugins: { datalabels: { anchor: 'end', align: 'end', color: INK, font: { weight: 'bold', size: 13 } } },
    scales: { xAxes: [{ ticks: { beginAtZero: true, stepSize: 1, fontColor: MUTED }, gridLines: { color: '#eeeeee' } }],
              yAxes: [{ ticks: { fontColor: INK, fontSize: 13 }, gridLines: { display: false } }] } } };
const jm = m.ai_health && m.ai_health.judge ? m.ai_health.judge : {};
const jTypes = Object.keys(jm);
const judgeChart = { type: 'bar',
  data: { labels: jTypes.map(t => t + ' (n=' + jm[t].n + ')'), datasets: [{ data: jTypes.map(t => jm[t].avg), backgroundColor: BLUE }] },
  options: { legend: { display: false }, plugins: { datalabels: { anchor: 'end', align: 'top', color: INK, font: { weight: 'bold', size: 13 } } },
    scales: { yAxes: [{ ticks: { beginAtZero: true, max: 5, stepSize: 1, fontColor: MUTED }, gridLines: { color: '#eeeeee' } }],
              xAxes: [{ ticks: { fontColor: MUTED }, gridLines: { display: false } }] } } };
return [{ json: { ...j, charts: {
  judge: { config: judgeChart, url: qc(judgeChart, 420, 220) },
  band_mix: { config: donut, url: qc(donut, 380, 220) },
  daily: { config: daily, url: qc(daily, 520, 240) },
  funnel: { config: funnel, url: qc(funnel, 520, 260) } } } }];

const raw = $input.first().json;
let r = raw;
if (r && Array.isArray(r.candidates)) r = { content: (r.candidates[0] || {}).content };
if (r && r.content && Array.isArray(r.content.parts)) r = r.content.parts.map(p => p.text || '').join('');
else if (r.content !== undefined) r = r.content;
if (typeof r === 'string') { try { r = JSON.parse(r.replace(/^```json?\s*|```\s*$/g, '')); } catch (e) { r = null; } }
const j = $('Build Charts').first().json;
const m = j.metrics, c = j.charts;
const narrative = (r && typeof r.narrative === 'string' && r.narrative.trim()) ? r.narrative.trim()
  : 'Narrative unavailable this week; all figures are in the tables and charts below.';
const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;');
const row = (k, v) => '<tr><td style="padding:6px 14px 6px 0;color:#707070">' + k + '</td><td style="padding:6px 0;color:#333;font-weight:600">' + v + '</td></tr>';
const appr = m.approval || {};
const apprTotal = (appr.approved || 0) + (appr.rejected || 0);
const apprRate = apprTotal ? Math.round((appr.approved || 0) * 100 / apprTotal) + '%' : 'n/a';
const cats = (m.top_categories || []).map(t => t.category + ' (' + t.count + ')').join(', ') || 'none';
const ah = m.ai_health || null;
const usd = (v) => '$' + (v == null ? '0' : v);
let aiSection = '<p style="color:#707070">No AI telemetry this week.</p>';
if (ah) {
  aiSection = (c.judge ? '<img src="' + c.judge.url + '" width="420" alt="Judge scores by artifact type, scale 1 to 5" style="max-width:100%">' : '') +
    '<table style="border-collapse:collapse;font-size:14px">' +
    row('LLM calls this week', ah.llm_calls) +
    row('Cost per lead (exact API tokens)', usd(ah.cost_per_lead_usd) + ' (free tier: actual spend 0)') +
    row('Latency p50 / p95', Math.round(ah.latency_p50_ms || 0) + ' ms / ' + Math.round(ah.latency_p95_ms || 0) + ' ms') +
    row('Schema-valid outputs', (ah.schema_validity_pct || 0) + '%') +
    row('Retries / fallbacks', (ah.retries || 0) + ' / ' + (ah.fallbacks || 0)) +
    '</table>';
}
const html = [
  '<div style="font-family:Segoe UI,Arial,sans-serif;max-width:640px;margin:0 auto;color:#333">',
  '<h2 style="margin:0 0 2px">' + esc(j.business_name) + ' - Weekly Sales Insights</h2>',
  '<p style="color:#707070;margin:0 0 18px">' + m.week_start + ' to ' + m.week_end + '</p>',
  '<p style="line-height:1.55">' + esc(narrative) + '</p>',
  '<h3 style="margin:22px 0 8px">Funnel</h3>',
  '<img src="' + c.funnel.url + '" width="520" alt="Funnel: received to sent" style="max-width:100%">',
  '<h3 style="margin:22px 0 8px">Lead quality</h3>',
  '<img src="' + c.band_mix.url + '" width="380" alt="Band mix" style="max-width:100%">',
  '<h3 style="margin:22px 0 8px">Daily enquiry volume</h3>',
  '<img src="' + c.daily.url + '" width="520" alt="Daily volume" style="max-width:100%">',
  '<h3 style="margin:22px 0 8px">Key numbers</h3>',
  '<table style="border-collapse:collapse;font-size:14px">',
  row('Enquiries received', m.volume_total),
  row('Replies sent', (m.funnel || {}).sent || 0),
  row('Approval rate', apprRate + ' (' + (appr.approved || 0) + ' approved / ' + (appr.rejected || 0) + ' rejected)'),
  row('Avg time to draft', (m.avg_mins_to_draft != null ? m.avg_mins_to_draft + ' min' : 'n/a')),
  row('Waiting on humans', (m.needs_review || 0) + ' need review'),
  row('Top recommended categories', esc(cats)),
  '</table>',
  '<h3 style="margin:22px 0 8px">AI health</h3>',
  aiSection,
  '<p style="color:#9a9a9a;font-size:12px;margin-top:22px">Every number is computed from vaibhavcapstone_* rows (leads, events, llm_calls, judge_scores) and reproducible by SQL. Charts contain aggregates only - no personal data.</p>',
  '</div>'
].join('');
return [{ json: { business_id: j.business_id, business_name: j.business_name, reviewer_email: j.reviewer_email,
  sender_identity: j.sender_identity, metrics: m, narrative, charts: c, report_html: html } }];

const j = $input.first().json;
let out;
if (Array.isArray(j.candidates)) {
  out = { ...j, __model: 'gemini-2.5-flash', __fallback: false };
} else if (Array.isArray(j.choices)) {
  const u = j.usage || {};
  out = { candidates: [{ content: { parts: [{ text: (j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '' }] },
    finishReason: (j.choices[0] && j.choices[0].finish_reason) || null }],
    usageMetadata: { promptTokenCount: u.prompt_tokens || 0, candidatesTokenCount: u.completion_tokens || 0, thoughtsTokenCount: 0 },
    __model: 'gpt-4o-mini', __fallback: true };
} else {
  out = { candidates: [], usageMetadata: {}, __model: 'unknown', __fallback: true };
}
return [{ json: out }];
